func (this *CTabFolderRenderer) DrawSelected(itemIndex int32, gcLike GCLike, boundsLike RectangleLike, state int32) {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	var bounds *Rectangle
	if boundsLike != nil {
		bounds = boundsLike.AsRectangle()
	}
	_ = bounds
	var item *CTabItem = this.parent.items[itemIndex]
	var x int32 = bounds.X
	var y int32 = bounds.Y
	var height int32 = bounds.Height
	var width int32 = bounds.Width
	var borderLeft int32
	if this.parent.borderVisible {
		borderLeft = 1
	} else {
		borderLeft = 0
	}
	var borderRight int32 = borderLeft
	var borderTop int32
	if this.parent.onBottom {
		borderTop = borderLeft
	} else {
		borderTop = 0
	}
	var borderBottom int32
	if this.parent.onBottom {
		borderBottom = 0
	} else {
		borderBottom = borderLeft
	}
	var size *Point = this.parent.impl.getSize_()
	var rightEdge int32 = int32(math.Min(float64(x+width), float64(this.parent.GetRightItemEdge(gc))))
	if (state & BACKGROUND) != 0 {
		var highlight_header int32
		if (this.parent.impl.getStyle_() & FLAT) != 0 {
			highlight_header = 1
		} else {
			highlight_header = 3
		}
		var xx int32 = borderLeft
		var yy int32
		if this.parent.onBottom {
			yy = size.Y - borderBottom - this.parent.tabHeight - highlight_header
		} else {
			yy = borderTop + this.parent.tabHeight + 1
		}
		var ww int32 = size.X - borderLeft - borderRight
		var hh int32 = highlight_header - 1
		var shape []int32 = []int32{xx, yy, xx + ww, yy, xx + ww, yy + hh, xx, yy + hh}
		if this.parent.selectionGradientColors != (nil) && !this.parent.selectionGradientVertical {
			this.DrawBackgroundGcShapeSelected(gc, shape, this.parent.ShouldHighlight())
		} else {
			var cond7 *Color
			if this.parent.ShouldHighlight() {
				cond7 = this.parent.selectionBackground
			} else {
				cond7 = this.parent.GetBackground()
			}
			gc.SetBackground(cond7)
			gc.FillRectangle(xx, yy, ww, hh)
		}
		if this.parent.single {
			if !item.showing {
				return
			}
		} else {
			if !item.showing {
				var x1 int32 = int32(math.Max(float64(0), float64(borderLeft-1)))
				var y1 int32
				if this.parent.onBottom {
					y1 = y - 1
				} else {
					y1 = y + height
				}
				var x2 int32 = size.X - borderRight
				gc.SetForeground(this.parent.GetDisplay().impl.getSystemColor_(CTabFolderRendererBORDER1_COLOR))
				gc.DrawLine(x1, y1, x2, y1)
				return
			}
			shape = make([]int32, 12)
			if this.parent.onBottom {
				var index int32 = 0
				t8 := index
				index++
				shape[t8] = x
				t9 := index
				index++
				shape[t9] = y - 1
				t10 := index
				index++
				shape[t10] = x
				t11 := index
				index++
				shape[t11] = y - 1
				t12 := index
				index++
				shape[t12] = x
				t13 := index
				index++
				shape[t13] = y + height
				if borderLeft == 0 && itemIndex == this.parent.firstIndex {
					shape[index-2] += x
					shape[index-1] += y + height
				}
				t14 := index
				index++
				shape[t14] = rightEdge - 1
				t15 := index
				index++
				shape[t15] = y + height - 1
				t16 := index
				index++
				shape[t16] = rightEdge - 1
				t17 := index
				index++
				shape[t17] = y - 1
				t18 := index
				index++
				shape[t18] = rightEdge - 1
				t19 := index
				index++
				shape[t19] = y - 1
			} else {
				var index int32 = 0
				t20 := index
				index++
				shape[t20] = x
				t21 := index
				index++
				shape[t21] = y + height + 1
				t22 := index
				index++
				shape[t22] = x
				t23 := index
				index++
				shape[t23] = y + height + 1
				t24 := index
				index++
				shape[t24] = x
				t25 := index
				index++
				shape[t25] = y
				if borderLeft == 0 && itemIndex == this.parent.firstIndex {
					shape[index-2] += x
					shape[index-1] += y
				}
				t26 := index
				index++
				shape[t26] = rightEdge - 1
				t27 := index
				index++
				shape[t27] = y
				t28 := index
				index++
				shape[t28] = rightEdge - 1
				t29 := index
				index++
				shape[t29] = y + height + 1
				t30 := index
				index++
				shape[t30] = rightEdge - 1
				t31 := index
				index++
				shape[t31] = y + height + 1
			}
			var clipping *Rectangle = gc.GetClipping()
			var clipBounds *Rectangle = item.GetBounds()
			clipBounds.Height += 1
			if this.parent.onBottom {
				clipBounds.Y -= 1
			}
			var tabInPaint bool = clipping.IntersectsRect(clipBounds)
			if tabInPaint {
				if this.parent.selectionGradientColors != (nil) && !this.parent.selectionGradientVertical {
					this.DrawBackgroundGcShapeSelected(gc, shape, true)
				} else {
					var defaultBackground *Color
					if this.parent.ShouldHighlight() {
						defaultBackground = this.parent.selectionBackground
					} else {
						defaultBackground = this.parent.GetBackground()
					}
					var image *Image = this.parent.selectionBgImage
					var colors []*Color = this.parent.selectionGradientColors
					var percents []int32 = this.parent.selectionGradientPercents
					var vertical bool = this.parent.selectionGradientVertical
					xx = x
					if this.parent.onBottom {
						yy = y - 1
					} else {
						yy = y + 1
					}
					ww = width
					hh = height
					this.DrawBackgroundGcShapeXYWidthHeightDefaultBackgroundImageColorsPercentsVertical(gc, shape, xx, yy, ww, hh, defaultBackground, image, colors, percents, vertical)
				}
			}
			this.DrawHighlight(gc, bounds, state, rightEdge)
			if this.parent.selectionHighlightBarThickness > 0 {
				var previousColor *Color = gc.GetBackground()
				var cond32 int32
				if this.parent.ShouldHighlight() {
					cond32 = COLOR_LIST_SELECTION
				} else {
					cond32 = COLOR_WIDGET_DISABLED_FOREGROUND
				}
				gc.SetBackground(item.GetDisplay().impl.getSystemColor_(cond32))
				var highlightShape []int32 = jrt.CopyOf(shape, int32(len(shape)))
				var thickness int32 = this.parent.selectionHighlightBarThickness
				var onBottom bool = this.parent.onBottom
				var bottomY int32 = y + height - 1
				var highlightY int32
				if onBottom {
					highlightY = bottomY - thickness
				} else {
					highlightY = thickness + 1
				}
				highlightShape[int32(len(highlightShape))-3] = highlightY
				highlightShape[int32(len(highlightShape))-1] = highlightShape[int32(len(highlightShape))-3]
				highlightShape[3] = highlightShape[int32(len(highlightShape))-1]
				highlightShape[1] = highlightShape[3]
				gc.FillPolygon(highlightShape)
				gc.SetBackground(previousColor)
			}
			shape[0] = int32(math.Max(float64(0), float64(borderLeft-1)))
			if borderLeft == 0 && itemIndex == this.parent.firstIndex {
				if this.parent.onBottom {
					shape[1] = y + height - 1
				} else {
					shape[1] = y
				}
				shape[3] = shape[1]
				shape[5] = shape[3]
			}
			shape[int32(len(shape))-2] = size.X - borderRight + 1
			for i := int32(0); i < int32(len(shape))/2; i++ {
				if shape[2*i+1] == y+height+1 {
					shape[2*i+1] -= 1
				}
			}
			var borderColor *Color = this.parent.GetDisplay().impl.getSystemColor_(CTabFolderRendererBORDER1_COLOR)
			gc.SetForeground(borderColor)
			gc.DrawPolyline(shape)
			if !tabInPaint {
				return
			}
		}
	}
	if (state & FOREGROUND) != 0 {
		var trim *Rectangle = this.ComputeTrim(itemIndex, NONE, 0, 0, 0, 0)
		var xDraw int32 = x - trim.X
		if this.parent.single && this.ShouldAllocateCloseRect(item) {
			xDraw += item.closeRect.Width
		}
		var image *Image = item.impl.getImage_()
		if image != (nil) && !image.impl.isDisposed_() && this.parent.showSelectedImage {
			var imageBounds *Rectangle = image.GetBounds()
			var maxImageWidth int32 = rightEdge - xDraw - (trim.Width + trim.X)
			if !this.parent.single && item.closeRect.Width > 0 {
				maxImageWidth -= item.closeRect.Width + CTabFolderRendererINTERNAL_SPACING
			}
			if imageBounds.Width < maxImageWidth {
				var imageX int32 = xDraw
				var imageY int32 = y + (height-imageBounds.Height)/2
				var cond33 int32
				if this.parent.onBottom {
					cond33 = -1
				} else {
					cond33 = 1
				}
				imageY += cond33
				gc.DrawImage(image, imageX, imageY)
				xDraw += imageBounds.Width + CTabFolderRendererINTERNAL_SPACING
			}
		}
		xDraw += this.GetLeftTextMargin(item)
		var textWidth int32 = rightEdge - xDraw - (trim.Width + trim.X)
		if !this.parent.single && item.closeRect.Width > 0 {
			textWidth -= item.closeRect.Width + CTabFolderRendererINTERNAL_SPACING
		}
		if textWidth > 0 {
			var gcFont *Font = gc.GetFont()
			var cond34 *Font
			if item.font == (nil) {
				cond34 = this.parent.GetFont()
			} else {
				cond34 = item.font
			}
			gc.SetFont(cond34)
			if item.shortenedText == "" || item.shortenedTextWidth != textWidth {
				item.shortenedText = this.ShortenText(gc, item.impl.getText_(), textWidth)
				item.shortenedTextWidth = textWidth
			}
			var extent *Point = gc.TextExtentStringFlags(item.shortenedText, CTabFolderRendererFLAGS)
			var textY int32 = y + (height-extent.Y)/2
			var cond35 int32
			if this.parent.onBottom {
				cond35 = -1
			} else {
				cond35 = 1
			}
			textY += cond35
			var cond36 *Color
			if item.selectionForeground == (nil) {
				cond36 = this.parent.GetSelectionForeground()
			} else {
				cond36 = item.selectionForeground
			}
			gc.SetForeground(cond36)
			gc.DrawTextStringXYFlags(item.shortenedText, xDraw, textY, CTabFolderRendererFLAGS)
			gc.SetFont(gcFont)
			if this.parent.impl.isFocusControl_() {
				var orginalForeground *Color = gc.GetForeground()
				var orginalBackground *Color = gc.GetBackground()
				var display *Display = this.parent.GetDisplay()
				gc.SetBackground(display.impl.getSystemColor_(COLOR_BLACK))
				gc.SetForeground(display.impl.getSystemColor_(COLOR_WHITE))
				gc.DrawFocus(xDraw-1, textY-1, extent.X+2, extent.Y+2)
				gc.SetForeground(orginalForeground)
				gc.SetBackground(orginalBackground)
			}
		}
		if this.ShouldAllocateCloseRect(item) {
			this.DrawCloseGcCloseRectCloseImageStateShowDirtyIndicatorSelected(gc, item.closeRect, item.closeImageState, this.ShouldDrawDirtyIndicator(item), true)
		}
	}
}

func (this *CTabFolderRenderer) GetLeftTextMargin(itemLike CTabItemLike) int32 {
	var item *CTabItem
	if itemLike != nil {
		item = itemLike.AsCTabItem()
	}
	_ = item
	var margin int32 = 0
	if this.ShouldApplyLargeTextPadding(this.parent) {
		margin += this.GetLargeTextPadding(item)
		if this.ShouldAllocateCloseRect(item) {
			margin -= item.closeRect.Width / 2
		}
	}
	return margin
}

func (this *CTabFolderRenderer) DrawTabArea(gcLike GCLike, boundsLike RectangleLike, state int32) {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	var bounds *Rectangle
	if boundsLike != nil {
		bounds = boundsLike.AsRectangle()
	}
	_ = bounds
	var size *Point = this.parent.impl.getSize_()
	var borderColor *Color = this.parent.GetDisplay().impl.getSystemColor_(CTabFolderRendererBORDER1_COLOR)
	var tabHeight int32 = this.parent.tabHeight
	var style int32 = this.parent.impl.getStyle_()
	var borderLeft int32
	if this.parent.borderVisible {
		borderLeft = 1
	} else {
		borderLeft = 0
	}
	var borderRight int32 = borderLeft
	var borderTop int32
	if this.parent.onBottom {
		borderTop = borderLeft
	} else {
		borderTop = 0
	}
	var borderBottom int32
	if this.parent.onBottom {
		borderBottom = 0
	} else {
		borderBottom = borderLeft
	}
	var selectedIndex int32 = this.parent.selectedIndex
	var highlight_header int32
	if (style & FLAT) != 0 {
		highlight_header = 1
	} else {
		highlight_header = 3
	}
	if tabHeight == 0 {
		if (style&FLAT) != 0 && (style&BORDER) == 0 {
			return
		}
		var x1 int32 = borderLeft - 1
		var x2 int32 = size.X - borderRight
		var y1 int32
		if this.parent.onBottom {
			y1 = size.Y - borderBottom - highlight_header - 1
		} else {
			y1 = borderTop + highlight_header
		}
		var y2 int32
		if this.parent.onBottom {
			y2 = size.Y - borderBottom
		} else {
			y2 = borderTop
		}
		if borderLeft > 0 && this.parent.onBottom {
			y2 -= 1
		}
		var shape []int32 = []int32{x1, y1, x1, y2, x2, y2, x2, y1}
		if selectedIndex != -1 && this.parent.selectionGradientColors != (nil) && int32(len(this.parent.selectionGradientColors)) > 1 && !this.parent.selectionGradientVertical {
			this.DrawBackgroundGcShapeSelected(gc, shape, true)
		} else {
			if selectedIndex == -1 && this.parent.gradientColors != (nil) && int32(len(this.parent.gradientColors)) > 1 && !this.parent.gradientVertical {
				this.DrawBackgroundGcShapeSelected(gc, shape, false)
			} else {
				var cond37 *Color
				if selectedIndex != -1 && this.parent.ShouldHighlight() {
					cond37 = this.parent.selectionBackground
				} else {
					cond37 = this.parent.GetBackground()
				}
				gc.SetBackground(cond37)
				gc.FillPolygon(shape)
			}
		}
		if borderLeft > 0 {
			gc.SetForeground(borderColor)
			gc.DrawPolyline(shape)
		}
		return
	}
	var x int32 = int32(math.Max(float64(0), float64(borderLeft-1)))
	var y int32
	if this.parent.onBottom {
		y = size.Y - borderBottom - tabHeight
	} else {
		y = borderTop
	}
	var width int32 = size.X - borderLeft - borderRight + 1
	var height int32 = tabHeight - 1
	var shape []int32 = make([]int32, 8)
	if this.parent.onBottom {
		var index int32 = 0
		t38 := index
		index++
		shape[t38] = x
		t39 := index
		index++
		shape[t39] = y - highlight_header
		t40 := index
		index++
		shape[t40] = x
		t41 := index
		index++
		shape[t41] = y + height
		if borderLeft == 0 {
			shape[index-1] += 1
		}
		t42 := index
		index++
		shape[t42] = x + width
		t43 := index
		index++
		shape[t43] = y + height
		if borderLeft == 0 {
			shape[index-1] += 1
		}
		t44 := index
		index++
		shape[t44] = x + width
		t45 := index
		index++
		shape[t45] = y - highlight_header
	} else {
		var index int32 = 0
		t46 := index
		index++
		shape[t46] = x
		t47 := index
		index++
		shape[t47] = y + height + highlight_header + 1
		t48 := index
		index++
		shape[t48] = x
		t49 := index
		index++
		shape[t49] = y
		t50 := index
		index++
		shape[t50] = x + width
		t51 := index
		index++
		shape[t51] = y
		t52 := index
		index++
		shape[t52] = x + width
		t53 := index
		index++
		shape[t53] = y + height + highlight_header + 1
	}
	var single bool = this.parent.single
	var bkSelected bool = single && selectedIndex != -1
	this.DrawBackgroundGcShapeSelected(gc, shape, bkSelected)
	if selectedIndex == -1 {
		var x1 int32 = borderLeft
		var y1 int32
		if this.parent.onBottom {
			y1 = size.Y - borderBottom - tabHeight - 1
		} else {
			y1 = borderTop + tabHeight
		}
		var x2 int32 = size.X - borderRight
		gc.SetForeground(borderColor)
		gc.DrawLine(x1, y1, x2, y1)
	}
	if borderLeft > 0 {
		gc.SetForeground(borderColor)
		gc.DrawPolyline(shape)
	}
}

func (this *CTabFolderRenderer) DrawUnselected(index int32, gcLike GCLike, boundsLike RectangleLike, state int32) {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	var bounds *Rectangle
	if boundsLike != nil {
		bounds = boundsLike.AsRectangle()
	}
	_ = bounds
	var item *CTabItem = this.parent.items[index]
	var x int32 = bounds.X
	var y int32 = bounds.Y
	var height int32 = bounds.Height
	var width int32 = bounds.Width
	if !item.showing {
		return
	}
	var clipping *Rectangle = gc.GetClipping()
	if !clipping.IntersectsRect(bounds) {
		return
	}
	if (state & BACKGROUND) != 0 {
		if index > 0 && index < this.parent.selectedIndex {
			this.DrawLeftUnselectedBorder(gc, bounds, state)
		}
		if index > this.parent.selectedIndex {
			this.DrawRightUnselectedBorder(gc, bounds, state)
		}
	}
	if (state & FOREGROUND) != 0 {
		var trim *Rectangle = this.ComputeTrim(index, NONE, 0, 0, 0, 0)
		var xDraw int32 = x - trim.X
		var image *Image = item.impl.getImage_()
		if image != (nil) && !image.impl.isDisposed_() && this.parent.showUnselectedImage {
			var imageBounds *Rectangle = image.GetBounds()
			var maxImageWidth int32 = x + width - xDraw - (trim.Width + trim.X)
			if this.ShouldAllocateCloseRect(item) {
				maxImageWidth -= item.closeRect.Width + CTabFolderRendererINTERNAL_SPACING
			}
			if imageBounds.Width < maxImageWidth {
				var imageX int32 = xDraw
				var imageHeight int32 = imageBounds.Height
				var imageY int32 = y + (height-imageHeight)/2
				var cond54 int32
				if this.parent.onBottom {
					cond54 = -1
				} else {
					cond54 = 1
				}
				imageY += cond54
				var imageWidth int32 = imageBounds.Width * imageHeight / imageBounds.Height
				gc.DrawImageImageDestXDestYDestWidthDestHeight(image, imageX, imageY, imageWidth, imageHeight)
				xDraw += imageWidth + CTabFolderRendererINTERNAL_SPACING
			}
		}
		xDraw += this.GetLeftTextMargin(item)
		var textWidth int32 = x + width - xDraw - (trim.Width + trim.X)
		if this.ShouldAllocateCloseRect(item) {
			textWidth -= item.closeRect.Width + CTabFolderRendererINTERNAL_SPACING
		}
		if textWidth > 0 {
			var gcFont *Font = gc.GetFont()
			var cond55 *Font
			if item.font == (nil) {
				cond55 = this.parent.GetFont()
			} else {
				cond55 = item.font
			}
			gc.SetFont(cond55)
			if item.shortenedText == "" || item.shortenedTextWidth != textWidth {
				item.shortenedText = this.ShortenText(gc, item.impl.getText_(), textWidth)
				item.shortenedTextWidth = textWidth
			}
			var extent *Point = gc.TextExtentStringFlags(item.shortenedText, CTabFolderRendererFLAGS)
			var textY int32 = y + (height-extent.Y)/2
			var cond56 int32
			if this.parent.onBottom {
				cond56 = -1
			} else {
				cond56 = 1
			}
			textY += cond56
			var cond57 *Color
			if item.foreground == (nil) {
				cond57 = this.parent.impl.getForeground_()
			} else {
				cond57 = item.foreground
			}
			gc.SetForeground(cond57)
			gc.DrawTextStringXYFlags(item.shortenedText, xDraw, textY, CTabFolderRendererFLAGS)
			gc.SetFont(gcFont)
		}
		if this.ShouldAllocateCloseRect(item) {
			this.DrawCloseGcCloseRectCloseImageStateShowDirtyIndicatorSelected(gc, item.closeRect, item.closeImageState, this.ShouldDrawDirtyIndicator(item), false)
		}
	}
}

func (this *CTabFolderRenderer) GetFillColor() *Color {
	if this.fillColor == (nil) {
		this.fillColor = NewColorRgb(CTabFolderRendererCLOSE_FILL)
	}
	return this.fillColor
}

func (this *CTabFolderRenderer) GetChevronFont(displayLike DisplayLike) *Font {
	var display *Display
	if displayLike != nil {
		display = displayLike.AsDisplay()
	}
	_ = display
	if this.chevronFont == (nil) {
		var fd *FontData = this.parent.GetFont().GetFontData()[0]
		var fontHeight int32 = int32((fd.Height * CTabFolderRendererCHEVRON_FONT_SIZE_FACTOR))
		fd.SetHeight(fontHeight)
		this.chevronFont = NewFontDeviceFd(upcastDisplayToDevice(display), fd)
	}
	return this.chevronFont
}

func (this *CTabFolderRenderer) ResetChevronFont() {
	if this.chevronFont != (nil) {
		this.chevronFont.impl.dispose_()
		this.chevronFont = nil
	}
}

func (this *CTabFolderRenderer) ShortenText(gcLike GCLike, text string, width int32) string {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	return this.ShortenTextGcTextWidthEllipses(gc, text, width, CTabFolderRendererELLIPSIS)
}

func (this *CTabFolderRenderer) ShortenTextGcTextWidthEllipses(gcLike GCLike, text string, width int32, ellipses string) string {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	if gc.TextExtentStringFlags(text, CTabFolderRendererFLAGS).X <= width {
		return text
	}
	var ellipseWidth int32 = gc.TextExtentStringFlags(ellipses, CTabFolderRendererFLAGS).X
	var length int32 = jrt.StringLength(text)
	var layout *TextLayout = NewTextLayout(upcastDisplayToDevice(this.parent.GetDisplay()))
	layout.SetText(text)
	var end int32 = layout.GetPreviousOffset(length, MOVEMENT_CLUSTER)
	for end > 0 {
		text = jrt.Substring(text, 0, end)
		var l int32 = gc.TextExtentStringFlags(text, CTabFolderRendererFLAGS).X
		if l+ellipseWidth <= width {
			break
		}
		end = layout.GetPreviousOffset(end, MOVEMENT_CLUSTER)
	}
	layout.impl.dispose_()
	var cond58 string
	if end == 0 {
		cond58 = jrt.Substring(text, 0, 1)
	} else {
		cond58 = fmt.Sprintf("%s%s", text, ellipses)
	}
	return cond58
}
